contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test the relation between on-chain balance and the public Acc mapping and Collect behavior.
    // params: unlockTime for Put, putAmount to send with Put, collectAmount to attempt to Collect.
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance");

        // Record pre-state observations
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Call Put with value putAmount
        c.Put{value: putAmount}(unlockTime);

        // After Put, contract balance must increase by putAmount
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // Try Collect and capture whether it reverted. Collect is payable in the contract but does not require value from caller.
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observations after attempted Collect
        uint finalContractBalance = address(c).balance;
        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));

        // General rule asserted:
        // 1) The contract's recorded balance for this caller is never greater than the contract's Ether balance.
        // 2) If Collect succeeded (did not revert) then finalBalance = afterBalance - collectAmount and finalContractBalance = afterContractBalance - collectAmount.
        // 3) If Collect reverted then finalBalance == afterBalance and finalContractBalance == afterContractBalance.
        assert(
            // part 1: recorded balance <= contract on-chain balance
            finalBalance <= finalContractBalance
            // part 2 and 3 combined:
            && (
                (!collectReverted && finalBalance == afterBalance - collectAmount && finalContractBalance == afterContractBalance - collectAmount)
                || (collectReverted && finalBalance == afterBalance && finalContractBalance == afterContractBalance)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that a Put call with value `putAmount` increases both the contract's ether balance
    // and the caller's recorded Acc balance for this address by exactly putAmount.
    function run(uint unlockTime, uint putAmount) public payable {
        // ensure the test contract can send the requested amount
        require(address(this).balance >= putAmount);

        // observe before-state
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeAccBalance) = c.Acc(address(this));

        // perform the state-changing call: send putAmount with Put(unlockTime)
        c.Put{value: putAmount}(unlockTime);

        // observe after-state
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterAccBalance) = c.Acc(address(this));

        // The general invariant: contract balance rises by putAmount and the recorded per-address balance rises by putAmount
        assert(afterContractBalance == beforeContractBalance + putAmount && afterAccBalance == beforeAccBalance + putAmount);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: put some ether into c for this address, then attempt Collect and check the observable outcome.
    // Parameters:
    //  unlockTime: requested unlock time for Put
    //  putAmount: amount to send with Put (must be available to this contract)
    //  collectAmount: amount to attempt to Collect
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        // ensure test contract can send the requested putAmount
        require(address(this).balance >= putAmount);

        // Record before-state: contract balance and recorded per-address balance for this test contract
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeAccBalance) = c.Acc(address(this));

        // Make a Put call to deposit putAmount and set unlock time
        c.Put{value: putAmount}(unlockTime);

        // After Put: read balances
        uint midContractBalance = address(c).balance;
        (uint midUnlock, uint midAccBalance) = c.Acc(address(this));

        // Now try to Collect collectAmount and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterAccBalance) = c.Acc(address(this));

        // General rule (single assert): If Collect did NOT revert, then exactly two things must hold:
        // 1) contract's on-chain balance decreased by collectAmount (i.e., midContractBalance - afterContractBalance == collectAmount)
        // 2) recorded per-address balance decreased by collectAmount (midAccBalance - afterAccBalance == collectAmount)
        // If Collect reverted, nothing is required (we allow state to be unchanged or changed only by Put above).
        // We avoid underflow in the assert by rearranging to addition form.
        assert(reverted || (afterContractBalance + collectAmount == midContractBalance && afterAccBalance + collectAmount == midAccBalance));
    }

    // Allow receiving Ether if Collect sends Ether to this contract (not expected here but kept for completeness)
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll: optionally deposit some ether via Put (so Acc[msg.sender] may increase), then attempt Collect
    // and assert that if Collect did not revert then the recorded balance for this address did not increase.
    // Parameters:
    //   unlockTime: argument for Put
    //   putAmount: amount of wei to send with Put (must be available to this contract)
    //   collectAmount: amount to attempt to Collect
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Read recorded balance before any action
        (, uint beforeAcc) = c.Acc(address(this));

        // Make a Put call to potentially increase recorded balance
        c.Put{value: putAmount}(unlockTime);

        // Read recorded balance immediately before Collect
        (, uint midAcc) = c.Acc(address(this));

        // Try Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read recorded balance after Collect
        (, uint afterAcc) = c.Acc(address(this));

        // General rule: if Collect succeeded (did not revert) then the recorded balance after Collect is
        // less than or equal to the recorded balance just before Collect (Collect cannot increase the recorded balance).
        // If Collect reverted, we impose no constraint. This is a general invariant about Collect's effect.
        assert(reverted || afterAcc <= midAcc);
    }

    // Allow receiving Ether when Collect (or other calls) send Ether to this contract
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll optionally deposit via Put, then try Collect(amount).
    // Parameters:
    //  unlockTime: argument for Put
    //  putAmount: wei to send with Put (must be available to this contract)
    //  collectAmount: amount to attempt to Collect
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Observe balances before any action
        uint beforeContractBalance = address(c).balance;
        (, uint beforeAcc) = c.Acc(address(this));

        // Make a Put call to potentially increase recorded balance and c's balance
        c.Put{value: putAmount}(unlockTime);

        // Observe balances immediately before Collect
        uint beforeCollectContractBalance = address(c).balance;
        (, uint beforeCollectAcc) = c.Acc(address(this));

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint afterContractBalance = address(c).balance;
        (, uint afterAcc) = c.Acc(address(this));

        // General rule: if Collect succeeded then c's external balance decreased by at least collectAmount
        // (i.e., c paid out at least collectAmount), and the recorded Acc for this caller did not increase.
        // If Collect reverted, no constraint.
        assert(reverted || (beforeCollectContractBalance >= afterContractBalance &&
               beforeCollectContractBalance - afterContractBalance >= collectAmount &&
               afterAcc <= beforeCollectAcc));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: amount to send to Put, unlockTime to set, and amount to try to Collect.
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // initial observed values for this test caller (InvMutTest contract is msg.sender for c calls)
        // Note: Acc is public mapping; its getter returns (uint unlockTime, uint balance) for the caller
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;
        uint minSum = c.MinSum();

        // Perform Put by sending putAmount wei
        c.Put{value: putAmount}(unlockTime);

        // observe after Put
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Basic sanity: afterBalance increased by putAmount and contract balance increased accordingly
        // (we will assert a general rule at end; here we don't revert)

        // Now attempt to Collect collectAmount and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe final state
        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // General rule to assert:
        // If before calling Collect the holder satisfied (afterBalance >= minSum && afterBalance >= collectAmount && block.timestamp > afterUnlock)
        // then Collect must not revert, and if it succeeded (didn't revert) the contract's balance decreased by collectAmount
        // and the holder's recorded balance decreased by collectAmount.
        // Otherwise, either Collect reverted or (if it didn't) the balances changed accordingly as well.

        // We cannot read block.timestamp of the called contract; but afterUnlock was set by Put to max(unlockTime, block.timestamp_at_put).
        // To formulate a provable, observable condition we use the values we read: afterBalance, afterUnlock, minSum, collectAmount and reverted flag.

        // Assert the invariant:
        // If (afterBalance >= minSum && afterBalance >= collectAmount && afterUnlock < block.timestamp) then Collect did not revert and final balances decreased by collectAmount.
        // Otherwise, if Collect did not revert then final balances decreased by collectAmount.

        assert( (
            (afterBalance >= minSum && afterBalance >= collectAmount && afterUnlock < block.timestamp) ?
                (!reverted && finalContractBal + collectAmount == afterContractBal && finalBalance + collectAmount == afterBalance)
                :
                // if precondition not met, still if it didn't revert it must have transferred and updated balances; if it reverted, no balances change
                (reverted ? (finalContractBal == afterContractBal && finalBalance == afterBalance) : (finalContractBal + collectAmount == afterContractBal && finalBalance + collectAmount == afterBalance))
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
