    function run(uint sendAmount, uint unlockTime) public payable {
        require(address(this).balance >= sendAmount);

        // read balances before Put
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform Put sending sendAmount wei
        c.Put{value: sendAmount}(unlockTime);

        // read after values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // The general rule: afterBal == beforeBal + sendAmount and afterContractBal == beforeContractBal + sendAmount
