}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two amounts: depositAmt to send to Put, and collectAmt passed to Collect.
    // Ensure this test contract has enough Ether to send depositAmt.
    function run(uint depositAmt, uint collectAmt, uint unlockDelay) public payable {
        require(address(this).balance >= depositAmt);

        // Ensure MinSum condition by depositing at least 1 wei (we don't know MinSum exact value),
        // but we won't rely on that in the assertion — the rule only applies when Collect does not revert.

        // Record before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform a Put to ensure the caller has some recorded balance (may be zero if depositAmt==0)
        c.Put{value: depositAmt}(block.timestamp + unlockDelay);

        // After Put values
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Try Collect and capture whether it reverted
        bool reverted;
        // We must call Collect as a top-level statement; do the call inside try/catch to observe revert
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: If Collect did not revert and collectAmt != 0, then contract balance decreased by collectAmt
        // and the recorded balance decreased by collectAmt. If collectAmt == 0 and call didn't revert, balances unchanged.
        // We express this as: if not reverted then either collectAmt==0 and balances equal, or balances decreased by collectAmt.
        assert(
            reverted || (
                (collectAmt == 0 && afterContractBal == midContractBal && afterBal == midBal)
                || (collectAmt != 0 && midContractBal >= collectAmt && midBal >= collectAmt && afterContractBal + collectAmt == midContractBal && afterBal + collectAmt == midBal)
            )
        );
    }

    // receive to accept refunds/transfers if any
    receive() external payable {}
}

