        // Read recorded balance and contract balance before the Put
        (uint beforeUnlock, uint beforeRecorded) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform the Put call sending depositAmt wei
        c.Put{value: depositAmt}(unlockTime);

        // Read recorded balance and contract balance after the Put
        (uint afterUnlock, uint afterRecorded) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: afterRecorded == beforeRecorded + depositAmt AND afterContractBal == beforeContractBal + depositAmt
        assert(afterRecorded == beforeRecorded + depositAmt && afterContractBal == beforeContractBal + depositAmt);
    }

    // Allow receiving Ether if the contract sends any back
    receive() external payable {}
}

