contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: deposit some ether from this test to c using Put, then try Collect.
    // Inputs:
    // - depositAmt: amount to deposit into c via Put (must be sent as value)
    // - unlockTime: value passed to Put
    // - collectAmt: amount to request via Collect
    // Precondition: this contract must have enough balance to fund the deposit
    function run(uint depositAmt, uint unlockTime, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt);

        // Observe initial on-chain values
        uint beforeContractBal = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Make a deposit by calling Put with value depositAmt
        c.Put{value: depositAmt}(unlockTime);

        // Observe after deposit
        uint midContractBal = address(c).balance;
        (uint midUnlock, uint midBalance) = c.Acc(address(this));

        // Ensure deposit effected mapping and contract balance consistently
        // Now attempt to Collect collectAmt and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe final state
        uint afterContractBal = address(c).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // General rule:
        // If Collect succeeded (not reverted) then:
        //   - collectAmt must have been <= midBalance
        //   - block.timestamp must have been > midUnlock (we cannot read time, so infer by state change)
        //   - contract balance decreased by exactly collectAmt
        //   - recorded balance decreased by exactly collectAmt
        // If Collect reverted then both contract balance and recorded balance remain as after deposit
        assert(
            reverted
            ? (afterContractBal == midContractBal && afterBalance == midBalance)
            : (
                // on success: balances decreased by collectAmt
                afterContractBal + collectAmt == midContractBal
                && afterBalance + collectAmt == midBalance
            )
        );
    }

    // Allow receiving Ether so the test contract can fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test Put: depositAmt is sent as msg.value to c.Put(unlockTime).
    // Precondition: this test contract must have enough Ether to send depositAmt.
    function run(uint depositAmt, uint unlockTime) public payable {
        require(address(this).balance >= depositAmt);

        // Observe caller (this test contract) recorded state before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put and ensure we capture whether it reverts
        bool reverted;
        try c.Put{value: depositAmt}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: Put should not silently change balances except by adding depositAmt when it succeeds.
        // If the call reverted, no state change must be observable from public getters.
        // If the call succeeded, contract balance and recorded balance must each increase by exactly depositAmt,
        // and unlock time must be set to either the provided unlockTime (if in the future) or at least previous block.timestamp
        // (We cannot read block.timestamp, but the contract sets unlockTime = _unlockTime>block.timestamp?_unlockTime:block.timestamp;
        // so the new unlockTime must be >= beforeUnlock and >= (unlockTime when unlockTime>block.timestamp), but we conservatively assert it's >= beforeUnlock).

        assert(
            reverted
            ? (
                // no change on revert
                afterContractBal == beforeContractBal && afterBalance == beforeBalance && afterUnlock == beforeUnlock
              )
            : (
                // on success: both balances increase by depositAmt and unlockTime does not decrease
                afterContractBal == beforeContractBal + depositAmt
                && afterBalance == beforeBalance + depositAmt
                && afterUnlock >= beforeUnlock
              )
        );
    }

    // allow receiving Ether so this test contract can fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some initial funds via Put, then attempt Collect.
    // Params: depositAmt to Put, collectAmt to request in Collect, unlockTime to set when depositing.
    function run(uint depositAmt, uint collectAmt, uint unlockTime) public payable {
        require(address(this).balance >= depositAmt);
        // Observe before: recorded holder state and contract balance
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform a Put to ensure there's balance to collect from (this may revert)
        bool putReverted;
        try c.Put{value: depositAmt}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe after Put
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt Collect with collectAmt (may revert). Ensure collectAmt>0 to avoid trivial no-op.
        // No precondition on collectAmt so assertion must account for both revert and success.
        bool collectReverted;
        try c.Collect{value:0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // 1) Collect must never increase the contract's balance.
        // 2) If Collect succeeded, contract balance decreases by exactly collectAmt and recorded balance decreases by exactly collectAmt.
        // 3) If Collect reverted, contract balance and recorded balance remain as they were immediately before Collect.
        // We don't require that Collect ever succeeds; we account for both outcomes.
        assert(
            // never increases contract balance
            afterContractBal <= midContractBal
            && (
                collectReverted
                ? (
                    // no change on revert
                    afterContractBal == midContractBal && afterBalance == midBalance && afterUnlock == midUnlock
                  )
                : (
                    // on success: both contract and recorded balances decreased by exactly collectAmt
                    midContractBal == afterContractBal + collectAmt
                    && midBalance == afterBalance + collectAmt
                    // unlockTime should not increase due to Collect; it should remain equal
                    && afterUnlock == midUnlock
                  )
              )
        );
    }

    // allow receiving Ether so this test contract can fund deposits and receive refunds (if any)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params: amount to send in Put, and an unlockTime to pass through
    // We require this contract has enough balance to send `amount`.
    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount);

        // Observe before values for this test contract's holder record and contract balance
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Put with the provided amount; capture whether it reverted
        bool putReverted;
        try c.Put{value: amount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe after values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Put succeeded then both the recorded balance and the contract balance increased by exactly `amount`,
        // and unlockTime after the call is at least the block.timestamp at time of call (but we cannot read that here),
        // however Put sets unlockTime to either provided _unlockTime if > block.timestamp else block.timestamp.
        // We can at least assert unlockTime did not decrease.
        assert(
            putReverted
            ? (
                // on revert: nothing changed for balances or unlockTime
                afterContractBal == beforeContractBal && afterBalance == beforeBalance && afterUnlock == beforeUnlock
              )
            : (
                // on success: both balances increased by exactly amount and unlockTime did not decrease
                afterContractBal == beforeContractBal + amount
                && afterBalance == beforeBalance + amount
                && afterUnlock >= beforeUnlock
              )
        );
    }

    // receive to allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // sendAmount: amount to fund the holder via Put (so holder has balance)
    // collectAmt: amount to attempt to Collect
    // unlockTime: value passed to Put so we can make unlockTime in the past/future
    function run(uint sendAmount, uint collectAmt, uint unlockTime) public payable {
        // ensure this test contract can fund the Put call
        require(address(this).balance >= sendAmount);
        // Make an initial observation of holder record and contract balance
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt to deposit sendAmount using Put (may revert)
        bool putReverted;
        try c.Put{value: sendAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // After Put (successful or not) attempt Collect with collectAmt (may revert)
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // If collectAmt == 0 then Collect cannot decrease recorded balance; treat as no-withdraw case.
        // Otherwise, if Collect succeeded then the recorded balance decreased by exactly collectAmt
        // and the contract's balance did not increase (afterContractBal <= beforeContractBal + sendAmount).
        // If Collect reverted then recorded balance and contract balance did not decrease due to Collect.
        // We only observable-attribute the net effects relative to immediately before the Collect call.
        // To approximate that, we compare before* (state after Put) with after*.

        // Compute the "beforeCollect" observed values (state after Put attempt)
        uint beforeCollectUnlock = afterUnlock; // afterPut values are now in after* if Put succeeded; but if Put reverted they are equal to before*
        uint beforeCollectBal = afterBal;
        uint beforeCollectContractBal = afterContractBal;
        // However we need the state immediately before Collect. Because we already executed Collect, we cannot retrieve it directly.
        // Instead we conservatively use the values read right after Collect. To still make a provable general property,
        // we assert that if Collect succeeded then recorded balance decreased by exactly collectAmt and contract balance did not increase.

        assert(
            // If collectAmt is zero, then nothing meaningful to assert about decrease; require that balances did not increase unexpectedly
            (collectAmt == 0 && afterBal <= beforeBal + sendAmount && afterContractBal <= beforeContractBal + sendAmount)
            ||
            (collectAmt > 0 && (
                collectReverted
                ? (
                    // on revert: recorded balance and contract balance did not decrease compared to state after Put attempt
                    afterBal >= beforeBal && afterContractBal >= beforeContractBal
                  )
                : (
                    // on success: recorded balance decreased by exactly collectAmt and contract balance did not increase compared to state before this transaction's start
                    // We observe that afterBal + collectAmt == beforeBal + (putReverted ? 0 : sendAmount)
                    // and afterContractBal <= beforeContractBal + (putReverted ? 0 : sendAmount) && afterContractBal + collectAmt <= beforeContractBal + (putReverted ? 0 : sendAmount)
                    // For simplicity and provability, require recorded balance decreased by collectAmt and contract balance did not increase compared to before the whole run.
                    afterBal + collectAmt == beforeBal + (putReverted ? 0 : sendAmount)
                    && afterContractBal <= beforeContractBal + (putReverted ? 0 : sendAmount)
                  )
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put (via fallback or Put) and then attempt Collect.
    // Params:
    // - putAmount: Ether to deposit to c via Put
    // - unlockTime: parameter for Put
    // - collectAmount: amount to attempt to Collect
    // The test is payable so it can supply putAmount.
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance to fund Put");

        // Read before values: contract balance and stored Holder.balance for this test contract
        uint beforeContractBalance = address(c).balance;
        // Acc is public mapping; getter signature Acc(address) returns (uint unlockTime, uint balance)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Call Put to deposit putAmount and set unlock time
        c.Put{value: putAmount}(unlockTime);

        // After Put: contract balance must increase by putAmount, and stored balance increases by putAmount
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // Attempt Collect and capture whether it reverts
        bool collectReverted = false;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final state
        uint finalContractBalance = address(c).balance;
        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));

        // General rule asserted:
        // 1) Put must have increased the contract balance and stored balance by exactly putAmount.
        // 2) If Collect succeeded (did not revert) then:
        //      - before the Collect call, afterBalance must have been >= c.MinSum() and >= collectAmount,
        //        and block.timestamp must have been > afterUnlock (we can't read timestamp here, but Collect's
        //        success implies those conditions held), and finalBalance = afterBalance - collectAmount,
        //        and finalContractBalance = afterContractBalance - collectAmount.
        //    If Collect reverted then final balances remain unchanged from after values.
        // We express this as an assertion relating observable before/after/final values and the revert flag.

        assert(
            // Put effect holds
            afterContractBalance == beforeContractBalance + putAmount
            && afterBalance == beforeBalance + putAmount
            // Collect effect: either succeeded and decreased balances by collectAmount, or reverted and left them equal
            && (
                (!collectReverted
                    && finalBalance + collectAmount == afterBalance
                    && finalContractBalance + collectAmount == afterContractBalance)
                || (collectReverted
                    && finalBalance == afterBalance
                    && finalContractBalance == afterContractBalance)
            )
        );
    }

    // allow receiving Ether for funding the test
    receive() external payable {}
}

