    constructor(C _c) { c = _c; }

    // Params:
    // - deposit: amount to deposit via Put (to make a collectible balance)
    // - unlockTime: timestamp passed to Put (may be <= or > block.timestamp)
    // - collectAmt: amount attempted to Collect
    function run(uint deposit, uint unlockTime, uint collectAmt) public payable {
        // Need Ether to deposit
        require(address(this).balance >= deposit, "insufficient balance to fund Put");

        // Ensure this test's caller (InvMutTest) is the holder observed by c (it is, per problem statement)
        // Observe before values
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));
        uint minSum = c.MinSum();

        // Make a deposit to possibly enable Collect
        // Send deposit Ether to c via Put
        c.Put{value: deposit}(unlockTime);

        // Observe after deposit and before collect
        uint midContractBalance = address(c).balance;
        (uint midUnlock, uint midHolderBalance) = c.Acc(address(this));

        // Now attempt Collect and record whether it reverts
        bool reverted;
        // Collect is payable in signature but does not need msg.value; we call without value
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after collect
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterHolderBalance) = c.Acc(address(this));

        // Define the success condition required by the contract logic for Collect to proceed:
        // - holder balance (at time of call) >= MinSum
        // - holder balance >= collectAmt
        // - block.timestamp > holder.unlockTime
        // We can only observe stored values immediately before the Collect call: use midHolderBalance and midUnlock.
        bool shouldSucceed = (midHolderBalance >= minSum) && (midHolderBalance >= collectAmt) && (block.timestamp > midUnlock);

        // If Collect reverted then nothing should have changed in c's public observable state (balances remain as before the call).
        // If it succeeded then both contract balance and holder stored balance decreased by exactly collectAmt.
