            (reverted && afterContractBalance == midContractBalance && afterHolderBalance == midHolderBalance)
            || (!reverted && afterContractBalance + collectAmt == midContractBalance && afterHolderBalance + collectAmt == midHolderBalance && shouldSucceed)
        );
    }

    // Receive to accept Ether when deployed/funded externally
    receive() external payable {}
}

