contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will simulate a depositor (this contract) calling Put to deposit Ether, then call Collect.
    // Parameters: deposit amount, withdraw amount, unlockTime to set when depositing.
    function run(uint depositAmount, uint withdrawAmount, uint unlockTime) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // Initial observed values
        uint beforeAccBalance = c.Acc(address(this)).balance;
        uint beforeContractBalance = address(c).balance;

        // Perform Put to deposit depositAmount into c for this contract
        c.Put{value: depositAmount}(unlockTime);

        // Read after deposit
        uint afterAccBalance = c.Acc(address(this)).balance;
        uint afterContractBalance = address(c).balance;

        // After Put, recorded balance must have increased by depositAmount
        // (use an assert only at the end; so capture this fact via local variable)
        bool depositObserved = (afterAccBalance == beforeAccBalance + depositAmount) && (afterContractBalance >= beforeContractBalance + depositAmount);

        // Now try to Collect withdrawAmount. We must detect whether call reverted or the send returned false.
        bool collectReverted;
        bool sendSucceeded;
        // Calling Collect may revert; catch that
        try c.Collect(withdrawAmount) {
            collectReverted = false;
            // If Collect returned (non-reverting), then the contract attempted to send Ether to this contract.
            // We can observe balances to see if money arrived here (address(this).balance increased) and c's balance decreased.
            uint postAccBalance = c.Acc(address(this)).balance;
            uint postContractBalance = address(c).balance;
            // If send inside Collect succeeded, then this contract's balance should have increased by withdrawAmount (or by at least 0 if low-level callback used),
            // but because the low-level call forwards gas and this contract's fallback does nothing, the send will increase our balance by withdrawAmount.
            sendSucceeded = (postAccBalance + withdrawAmount == afterAccBalance) || (postContractBalance + withdrawAmount == afterContractBalance);
            // Note: we do not revert here; only record observations.
        } catch {
            collectReverted = true;
            sendSucceeded = false;
        }

        // Final observed Acc balance and contract balance
        uint finalAcc = c.Acc(address(this)).balance;
        uint finalContractBal = address(c).balance;

        // Now assert the general invariant:
        // If Collect did not revert and the internal send succeeded, then recorded balance decreased exactly by withdrawAmount
        // and contract balance decreased by at least withdrawAmount. Otherwise (reverted or send failed), recorded balance unchanged.
        assert(
            (
                !collectReverted && sendSucceeded
            ) ? (
                // when success: balance decreased by withdrawAmount and contract balance decreased by at least withdrawAmount
                finalAcc + withdrawAmount == afterAccBalance && afterContractBalance >= finalContractBal + withdrawAmount
            ) : (
                // when failure or revert: recorded balance unchanged (no premature subtraction)
                finalAcc == afterAccBalance
            )
        );
    }

    // receive to accept Ether from C when Collect sends funds
    receive() external payable {}
}

