    // balance decreased by exactly collectAmount as well; if Collect reverted,
    // then either preconditions for Collect weren't met (insufficient recorded
    // balance, below MinSum, or unlockTime not reached).
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount + 1 wei);
        // Ensure we can fund the Put call with putAmount
        // Note: c was freshly deployed by the checker; initial state is default.

