        // Read after values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule: if Collect succeeded, then the holder's recorded balance decreased by collectAmount
        // and the contract's Ether balance decreased by collectAmount. If Collect reverted, no requirement.
        // Note: require that Put succeeded so that Collect could possibly succeed; otherwise Collect may fail.
        assert(putReverted || collectReverted || (afterBalance + collectAmount == midBalance && afterContractBalance + collectAmount == midContractBalance));
    }

    // allow receiving Ether to fund test
    receive() external payable {}
}

