contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call run with an unlockTime and an amount to send to Put.
    // Ensure this contract has sufficient balance before sending.
    function run(uint _unlockTime, uint _amount) public payable {
        require(address(this).balance >= _amount, "insufficient test balance");

        // Read caller's (this contract) current recorded holder balance before Put
        (uint beforeUnlockTime, uint beforeBalance) = getHolder(msg.sender);
        // Read contract Ether balance before
        uint beforeContractBalance = address(c).balance;

        // Perform the action: call Put on c sending _amount wei
        bool reverted = false;
        try c.Put{value: _amount}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read afterwards
        (uint afterUnlockTime, uint afterBalance) = getHolder(msg.sender);
        uint afterContractBalance = address(c).balance;

        // If the call reverted, balances must be unchanged; if it succeeded, recorded balance increases by at least _amount
        assert(
            (reverted && afterBalance == beforeBalance && afterContractBalance == beforeContractBalance)
            ||
            (!reverted && afterBalance >= beforeBalance && (afterContractBalance == beforeContractBalance + _amount))
        );
    }

    // Helper to call the public getter for Acc (mapping). The compiler generates Acc(address) returning (uint unlockTime, uint balance).
    function getHolder(address who) internal returns (uint, uint) {
        // The auto-generated getter is a public function; calling it may be seen as a view, but we keep it as an external call.
        // Note: calling c.Acc(who) returns (uint unlockTime, uint balance).
        (uint u, uint b) = c.Acc(who);
        return (u, b);
    }

    // Allow receiving Ether so the test contract can be funded before calling run
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run attempts to Collect _am wei; ensure this contract has at least _am to satisfy potential Put calls if needed.
    // We use msg.sender of calls to c as this contract.
    function run(uint _am) public payable {
        require(address(this).balance >= 0, "no precondition");

        // Observe holder state and contract balance before the Collect attempt
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt to call Collect; per constraints this state-changing call must be a top-level statement
        bool reverted;
        try c.Collect{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // - The contract's Ether balance never increases because of Collect.
        // - If Collect reverted, observed holder balance and contract balance are unchanged.
        // - If Collect succeeded, then: afterBal <= beforeBal, the decrease (beforeBal - afterBal) is either 0 (if _am was 0)
        //   or exactly _am (when transfer occurred), and contract balance decreased by the same amount.
        assert(
            // contract balance never increases
            afterContractBal <= beforeContractBal
            && (
                // if reverted: no changes
                (reverted && afterBal == beforeBal && afterContractBal == beforeContractBal)
                ||
                // if succeeded: holder balance didn't increase and contract balance decreased by same delta
                (!reverted && afterBal <= beforeBal && (beforeBal - afterBal == beforeContractBal - afterContractBal))
            )
        );
    }

    // Allow receiving Ether so the test harness can fund this contract before calling run
    receive() external payable {}
}

