contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to attempt to Collect and a prior deposit amount to ensure there is some balance
    function run(uint depositAmount, uint collectAmount, uint unlockTime) public payable {
        // make sure this test contract can fund the deposit call
        require(address(this).balance >= depositAmount);

        // initial observed values for this test contract's holder record and contract balance
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // First, deposit depositAmount into c so that Collect might succeed later
        // We don't guard this call with try/catch: if it reverts the test run won't reach the final assert
        c.Put{value: depositAmount}(unlockTime);

        // Read values after deposit
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: if Collect succeeded then:
        //  - the holder's recorded balance decreased by exactly collectAmount (no other change to that holder's balance)
        //  - and the contract's on-chain balance decreased by at least collectAmount (the external call may forward less on failure, but success implies funds left c)
        // If Collect reverted, we accept any outcome.
        assert(reverted || (midBal >= collectAmount && midBal - afterBal == collectAmount && midContractBal >= afterContractBal && midContractBal - afterContractBal >= collectAmount));
    }

    receive() external payable {}
}
